code.cpp:
int twice(int x) {
  return x * 2;
}

void blink(int pin) {
  digitalWrite(pin, HIGH);
  delay(200);
  digitalWrite(pin, LOW);
  delay(200);
}

void setup() {
  pinMode(13, OUTPUT);
  Serial.begin(9600);
  Serial.println(twice(21));
}

void loop() {
  blink(13);
}

