code.cpp:
void setup() {
  Serial.begin(9600);
  pinMode(8, OUTPUT);
  pinMode(9, OUTPUT);
}

void loop() {
  if (Serial.available() > 0) {
    char key = Serial.read();
    switch (key) {
      case 'a':
        digitalWrite(8, HIGH);
        break;
      case 'b':
        digitalWrite(9, HIGH);
        break;
      default:
        digitalWrite(8, LOW);
        digitalWrite(9, LOW);
        break;
    }
  }
}

