code.cpp:
void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(13, OUTPUT);
}

void loop() {
  bool a = digitalRead(2) == LOW;
  bool b = digitalRead(3) == LOW;
  if (a and b) {
    digitalWrite(13, HIGH);
  } else if (a or b) {
    digitalWrite(13, millis() / 200 % 2);
  } else if (not a) {
    digitalWrite(13, LOW);
  }
}

