void setup() {
  Serial.begin(9600);
  pinMode(12, OUTPUT);
  pinMode(11, INPUT);
}

void loop() {
  digitalWrite(12, LOW);
  delayMicroseconds(2);
  digitalWrite(12, HIGH);
  delayMicroseconds(10);
  digitalWrite(12, LOW);
  unsigned long t = pulseIn(11, HIGH, 30000);
  Serial.println(t * 0.0343 / 2);
  delay(500);
}

