code.cpp:
volatile long steps = 0;

void turned() {
  if (digitalRead(3) == digitalRead(2)) {
    steps--;
  } else {
    steps++;
  }
}

void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT);
  pinMode(3, INPUT);
  attachInterrupt(digitalPinToInterrupt(2), turned, CHANGE);
}

void loop() {
  Serial.println(steps);
  delay(200);
}

