volatile int count = 0;

void tick() {
  count++;
}

void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(2), tick, FALLING);
}

void loop() {
  if (count >= 10) {
    detachInterrupt(digitalPinToInterrupt(2));
    Serial.println(count);
  }
  delay(100);
}

