#include <LiquidCrystal.h>

LiquidCrystal lcd(7, 8, 9, 10, 11, 12);

void setup() {
  lcd.begin(16, 2);
  lcd.print("Soga Arduino 2026");
}

void loop() {
  for (int i = 0; i < 5; i++) {
    lcd.scrollDisplayLeft();
    delay(400);
  }
  for (int i = 0; i < 5; i++) {
    lcd.scrollDisplayRight();
    delay(400);
  }
  lcd.noDisplay();
  delay(500);
  lcd.display();
  delay(500);
}

