#include <Setswana.h>

RTC_DS3231 rtc;

lefela simolola() {
  Seriale.tshimologo(9600);
  rtc.tshimologo();
}

lefela boeletsa() {
  Letlha_le_nako t = rtc.jaanong();
  Seriale.bontsha(t.ngwaga());
  Seriale.bontsha('/');
  Seriale.bontsha(t.kgwedi());
  Seriale.bontsha('/');
  Seriale.bontsha(t.letsatsi());
  Seriale.bontsha(' ');
  Seriale.bontsha(t.ura());
  Seriale.bontsha(':');
  Seriale.bontsha(t.motsotso());
  Seriale.bontsha(':');
  Seriale.bontsha(t.ya_bobedi());
  Seriale.bontsha("  ");
  Seriale.bontsha_mola(t.letsatsi_la_beke());
  ema(1000);
}

