#include <SevSeg.h>

SevSeg sev;

void setup() {
  byte digitPins[] = {2, 3, 4, 5};
  byte segmentPins[] = {6, 7, 8, 9, 10, 11, 12, 13};
  sev.begin(COMMON_CATHODE, 4, digitPins, segmentPins, false);
  sev.setBrightness(90);
}

void loop() {
  sev.setNumber(millis() / 1000, 0);
  sev.refreshDisplay();
}

